import sys

def solve(n, m):
    if n % 2 == 0 and m % 2 == 0:
        k = 1
        teleporters = [(n, m, 1, 1)]
        path = []
        for i in range(1, n + 1):
            if i % 2 == 1:
                path.extend([(i, j) for j in range(1, m + 1)])
            else:
                path.extend([(i, j) for j in range(m, 0, -1)])
        path.append((1, 1))
    else:
        k = 0
        path = []
        for i in range(1, n + 2):
